const { test, describe } = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { loadConfig } = require('../config-loader');

function writeTempConfig(content) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'config-loader-'));
  const filePath = path.join(dir, 'config.json');
  fs.writeFileSync(filePath, JSON.stringify(content));
  return filePath;
}

describe('loadConfig', () => {
  test('returns defaults when the file is missing', () => {
    const missing = path.join(os.tmpdir(), 'config-loader-missing', 'config.json');
    const defaults = { port: 8080, debug: true };
    assert.deepEqual(loadConfig(missing, defaults), defaults);
  });

  test('merges defaults with user values', () => {
    const file = writeTempConfig({ port: 3000 });
    const config = loadConfig(file, { port: 8080, host: 'localhost', debug: true });
    assert.deepEqual(config, { port: 3000, host: 'localhost', debug: true });
  });

  test('preserves user values when they conflict with defaults', () => {
    const file = writeTempConfig({ port: 3000, debug: false, db: { host: 'prod-db' } });
    const config = loadConfig(file, {
      port: 8080,
      debug: true,
      db: { host: 'localhost', port: 5432 },
    });
    assert.deepEqual(config, {
      port: 3000,
      debug: false,
      db: { host: 'prod-db', port: 5432 },
    });
  });
});
